using System.Linq;using UnityEditor;using UnityEngine;
namespace XuanwuTools { public static class MaterialNormalizer {
 [MenuItem(Common.Menu+"07 Normalize selected copied rock materials")] public static void Normalize()=>Common.Run(()=>{if(EditorApplication.isPlayingOrWillChangePlaymode)throw new System.Exception("Not in Play Mode");var mats=Selection.objects.OfType<Material>().Where(m=>AssetDatabase.GetAssetPath(m).StartsWith("Assets/XuanwuGenerated/")).ToArray();if(mats.Length==0)throw new System.Exception("Select copied materials under Assets/XuanwuGenerated");if(!Common.Confirm("Material dry-run",$"{mats.Length} rock materials: apply mild neutral-cool tint (K1 only), zero metallic, smoothness .2 where supported. K2 requires texture processing first."))return;foreach(var m in mats){Undo.RecordObject(m,"Normalize rock");foreach(string prop in new[]{"_BaseColor","_Color"})if(m.HasProperty(prop)){m.SetColor(prop,new Color(.78f,.82f,.88f,1));break;}if(m.HasProperty("_Metallic"))m.SetFloat("_Metallic",0);if(m.HasProperty("_Smoothness"))m.SetFloat("_Smoothness",.2f);EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}});}}
